// Process the content from Google Sheets
const items = $input.all();
const contentItems = items.map(item => item.json);

// Filter for this month's content
const now = new Date();
const currentMonth = now.getMonth();
const currentYear = now.getFullYear();

// Filter content marked for this month
const thisMonthContent = contentItems.filter(item => {
  if (!item.month || !item.year) return false;

  const itemMonth = parseInt(item.month) - 1; // Convert 1-12 to 0-11
  const itemYear = parseInt(item.year);

  return itemMonth === currentMonth && itemYear === currentYear;
});

// If no content for this month, use the most recent content
let selectedContent = thisMonthContent;
if (selectedContent.length === 0) {
  // Sort by date (most recent first)
  const sortedContent = contentItems
    .filter(item => item.month && item.year)
    .sort((a, b) => {
      const aDate = new Date(parseInt(a.year), parseInt(a.month) - 1);
      const bDate = new Date(parseInt(b.year), parseInt(b.month) - 1);
      return bDate - aDate;
    });

  // Take the most recent items (up to 5)
  selectedContent = sortedContent.slice(0, 5);
}

// Format the content for the newsletter
const formattedContent = selectedContent.map(item => ({
  title: item.title || 'Coaching Insight',
  content: item.content || 'No content available',
  link: item.link || null
}));

// Get month name for the newsletter
const monthNames = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];
const newsletterMonth = monthNames[currentMonth];

return {
  newsletterMonth,
  newsletterYear: currentYear,
  contentItems: formattedContent,
  contentCount: formattedContent.length,
  timestamp: now.toISOString()
};

// Process the client list from Google Sheets
const items = $input.all();
const clients = items.map(item => item.json);

// Filter for active clients with valid email addresses
const activeClients = clients.filter(client => {
  // Check for valid email
  const hasValidEmail = client.email && 
    client.email.includes('@') && 
    client.email.includes('.');

  // Check if client is active
  const isActive = client.status && 
    client.status.toLowerCase() === 'active';

  // Check if client has opted in to newsletter
  const hasOptedIn = client.newsletter_optin && 
    client.newsletter_optin.toLowerCase() === 'yes';

  return hasValidEmail && isActive && hasOptedIn;
});

// Format client data for personalization
const formattedClients = activeClients.map(client => ({
  email: client.email,
  firstName: client.first_name || 'Valued Client',
  lastName: client.last_name || '',
  fullName: `${client.first_name || 'Valued'} ${client.last_name || 'Client'}`,
  coachingType: client.coaching_type || 'Personal Development',
  joinDate: client.join_date || 'recently'
}));

return {
  clients: formattedClients,
  clientCount: formattedClients.length,
  timestamp: new Date().toISOString()
};

// Process the OpenAI response and prepare for email sending
const newsletterHtml = $input.item.json.text || $input.item.json.content;

// Store the raw newsletter template
const newsletterTemplate = newsletterHtml;

// Get client data for personalization
const clients = $node["Code - Process Clients"].json.clients;

// Create personalized newsletters for each client
const personalizedNewsletters = clients.map(client => {
  // Replace personalization tokens
  let personalized = newsletterTemplate
    .replace(/{{FIRST_NAME}}/g, client.firstName)
    .replace(/{{FULL_NAME}}/g, client.fullName)
    .replace(/{{COACHING_TYPE}}/g, client.coachingType);

  return {
    email: client.email,
    firstName: client.firstName,
    lastName: client.lastName,
    personalizedContent: personalized
  };
});

// Create a test email for verification
const testEmail = {
  email: "test@example.com",
  firstName: "Test",
  lastName: "User",
  personalizedContent: newsletterTemplate
    .replace(/{{FIRST_NAME}}/g, "Test")
    .replace(/{{FULL_NAME}}/g, "Test User")
    .replace(/{{COACHING_TYPE}}/g, "Test Coaching")
};

return {
  newsletterMonth: $node["Code - Process Content"].json.newsletterMonth,
  newsletterYear: $node["Code - Process Content"].json.newsletterYear,
  newsletterTemplate,
  personalizedNewsletters,
  clientCount: clients.length,
  testEmail
};

// Process each client for email sending
const newsletters = $node["Code - Prepare Emails"].json.personalizedNewsletters;
const currentIndex = $input.item.index;

if (currentIndex < newsletters.length) {
  const client = newsletters[currentIndex];

  return {
    email: client.email,
    firstName: client.firstName,
    lastName: client.lastName,
    personalizedContent: client.personalizedContent,
    index: currentIndex
  };
} else {
  return {
    email: null,
    firstName: null,
    lastName: null,
    personalizedContent: null,
    index: currentIndex
  };
}

// Log email sending for tracking
return {
  email: $node["Code - Process Each Client"].json.email,
  firstName: $node["Code - Process Each Client"].json.firstName,
  lastName: $node["Code - Process Each Client"].json.lastName,
  sentAt: new Date().toISOString(),
  status: "Sent",
  newsletterMonth: $node["Code - Prepare Emails"].json.newsletterMonth,
  newsletterYear: $node["Code - Prepare Emails"].json.newsletterYear
};

// Process completion of email sending
return {
  totalEmails: $node["Code - Prepare Emails"].json.clientCount,
  newsletterMonth: $node["Code - Prepare Emails"].json.newsletterMonth,
  newsletterYear: $node["Code - Prepare Emails"].json.newsletterYear,
  completedAt: new Date().toISOString()
};

